code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the repeated one-dimensional color key, either horizontal or vertical.
    colors = None
    for axis in (0, 1):
        outer, inner = (h, w) if axis == 0 else (w, h)
        for pos in range(outer):
            for start in range(inner):
                for end in range(start + 3, inner + 1):
                    seq = [grid[pos][j] for j in range(start, end)] if axis == 0 else [grid[j][pos] for j in range(start, end)]
                    if 0 in seq:
                        break
                    # Key is repeated in at least three adjacent lines.
                    def matches(line):
                        vals = [grid[line][j] for j in range(start, end)] if axis == 0 else [grid[j][line] for j in range(start, end)]
                        return vals == seq
                    if all(matches(k) for k in range(pos, min(pos + 3, outer))):
                        if pos + 2 < outer and all(matches(k) for k in range(pos, pos + 3)):
                            colors = seq
                            break
                if colors: break
            if colors: break
        if colors: break
    if colors is None:
        raise ValueError("color key not found")
    # The 1-colored exemplar is separate from the key.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    # Remove key cells; the main silhouette is the 8-connected component of 1s.
    seed = min(pts)
    todo = [seed]; seen = {seed}
    while todo:
        r, c = todo.pop()
        for rr in range(max(0, r-1), min(h, r+2)):
            for cc in range(max(0, c-1), min(w, c+2)):
                if grid[rr][cc] == 1 and (rr, cc) not in seen:
                    seen.add((rr, cc)); todo.append((rr, cc))
    pts = list(seen)
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    shape = [[grid[r][c] == 1 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    idx = colors.index(1)
    out = [[0]*w for _ in range(h)]
    top = r0 - idx*len(shape)
    for i, color in enumerate(colors):
        for dr, row in enumerate(shape):
            for dc, on in enumerate(row):
                if on:
                    out[top+i*len(shape)+dr][c0+dc] = color
    return out
'''
